:root {
  color-scheme: light dark;
  --surface: light-dark(#ffffff, #171717);
  --ink: light-dark(#111111, #fafafa);
}
[data-theme="light"] { color-scheme: light; }
[data-theme="dark"] { color-scheme: dark; }
.header, .card { background: var(--surface); color: var(--ink); }
.button { background: var(--ink); color: var(--surface); }

:root { --bg: #ffffff; --fg: #111111; }
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) { --bg: #171717; --fg: #fafafa; }
}
:root[data-theme="dark"] { --bg: #171717; --fg: #fafafa; }
.header, .card { background: var(--bg); color: var(--fg); }
.button { background: var(--fg); color: var(--bg); }

